import java.util.*;
import java.nio.file.*;
import javax.microedition.io.Connector;

/** Moderator actions through three unchanged original client instances. */
public class V4RoomModerationIntegration extends V4RoomIntegration {
 static final Path moderationRoot=Paths.get("data/applets/integration/room-moderation-out");
 static void peerMark(String peer,String name)throws Exception{until(peer+" reached "+name,()->Files.exists(moderationRoot.resolve(peer).resolve(name)));}
 static void action(int opcode,String target,int response)throws Exception{request(opcode,response,()->method(bc,"a",void.class,short.class,String.class,String.class).invoke(network,(short)opcode,target,"Lobby"));}
 static void roles(String capture,String... expected)throws Exception{
  while(!((Vector)get(canvas,"aI")).isEmpty())method(cc,"j",void.class).invoke(canvas);selectRoom("Lobby");method(cc,"k",void.class).invoke(canvas);request(707,708,()->method(bc,"a",void.class,short.class,String.class).invoke(network,(short)707,"Lobby"));until("original moderated participant popup constructed",()->method(cc,"i",Class.forName("y")).invoke(canvas)!=null);
  Object popup=method(cc,"i",Class.forName("y")).invoke(canvas);int count=(Integer)method(popup.getClass(),"c",int.class).invoke(popup);Map<String,Integer> actual=new TreeMap<>(),want=new TreeMap<>();for(String e:expected){String[] pair=e.split(":");want.put(pair[0],Integer.parseInt(pair[1]));}
  for(int i=0;i<count;i++)actual.put((String)method(popup.getClass(),"a",String.class,int.class).invoke(popup,i),(Integer)method(popup.getClass(),"c",int.class,int.class).invoke(popup,i));if(count!=want.size()||!actual.equals(want))throw new AssertionError("Original participant roles "+actual+", expected "+want);
  save(capture);Files.writeString(out.resolve(capture+"-model.txt"),actual+"\n1=moderator; 2=muted; 3=ordinary (original popup item selector).\n");System.out.println("PASS original participant roles "+actual);method(cc,"k",void.class).invoke(canvas);
 }
 static void kickNotice()throws Exception{
  until("original kick notification5 queued",()->Connector.count("RX",5)>0&&!((Vector)get(canvas,"aL")).isEmpty());selectRoom("Lobby");save("kick-notification");until("original kick information popup rendered",()->!((Vector)get(canvas,"aI")).isEmpty());Vector dialogs=(Vector)get(canvas,"aI");Object popup=dialogs.lastElement();Vector lines=(Vector)field(popup.getClass(),"a",Vector.class).get(popup);StringBuilder text=new StringBuilder();for(Object line:lines)text.append(line).append(' ');String body=text.toString().replaceAll("\\s+"," ").trim();if(!body.contains("You were kicked from Lobby by alice."))throw new AssertionError("Kick popup text mismatch: "+body);Files.writeString(out.resolve("kick-notification-model.txt"),body+"\n");if(roomTab("Lobby")<0)throw new AssertionError("Expected original room tab to remain after notification5");System.out.println("PASS original kick popup; room tab remains until user closes it");Object ok=field(cc,"bS",javax.microedition.lcdui.Command.class).get(canvas);method(cc,"commandAction",void.class,javax.microedition.lcdui.Command.class,javax.microedition.lcdui.Displayable.class).invoke(canvas,ok,canvas);until("original OK action dismissed kick notification",()->((Vector)get(canvas,"aL")).isEmpty()&&((Vector)get(canvas,"aI")).isEmpty());
 }
 static void alice()throws Exception{
  peerMark("bob","joined");peerMark("carol","joined");roles("participants-before-mute","alice:1","bob:3","carol:3");peerMark("bob","unauthorized-kick-denied");action(709,"bob",1);roles("participants-muted","alice:1","bob:2","carol:3");mark("bob-muted");peerMark("bob","muted-send-denied");sendRoom("Lobby","Room message while muted",1);peerMark("bob","received-while-muted");peerMark("carol","received-while-muted");
  if(wireHasRoomText("Lobby","MUTED send must fail"))throw new AssertionError("Moderator received a rejected muted send");action(710,"bob",1);roles("participants-unmuted","alice:1","bob:3","carol:3");mark("bob-unmuted");expectRoom("Lobby","Bob unmuted reply","room-unmuted-reply");peerMark("carol","unmuted-reply-received");action(706,"carol",1);roles("participants-after-kick","alice:1","bob:3");mark("carol-kicked");peerMark("carol","postkick-send-denied");sendRoom("Lobby","Lobby after Carol kick",1);peerMark("bob","postkick-message-received");mark("final-sent");peerMark("carol","no-postkick-delivery");mark("finished");
 }
 static void bob()throws Exception{
  peerMark("alice","joined");peerMark("carol","joined");action(706,"alice",0);until("original protected-moderator kick error dialog",()->!((Vector)get(canvas,"aI")).isEmpty());save("unauthorized-kick-denied");method(cc,"j",void.class).invoke(canvas);mark("unauthorized-kick-denied");peerMark("alice","bob-muted");sendRoom("Lobby","MUTED send must fail",0);Thread.sleep(200);selectRoom("Lobby");save("muted-send-denied");mark("muted-send-denied");expectRoom("Lobby","Room message while muted","room-receives-while-muted");mark("received-while-muted");peerMark("alice","bob-unmuted");sendRoom("Lobby","Bob unmuted reply",1);expectRoom("Lobby","Lobby after Carol kick","room-after-carol-kick");mark("postkick-message-received");peerMark("alice","finished");
 }
 static void carol()throws Exception{
  expectRoom("Lobby","Room message while muted","room-before-kick");if(wireHasRoomText("Lobby","MUTED send must fail"))throw new AssertionError("Room member received a rejected muted send");mark("received-while-muted");expectRoom("Lobby","Bob unmuted reply","room-unmuted-reply");mark("unmuted-reply-received");peerMark("alice","carol-kicked");kickNotice();sendRoom("Lobby","KICKED send must fail",0);Thread.sleep(200);if(roomTab("Lobby")>=0){selectRoom("Lobby");save("postkick-send-denied");}mark("postkick-send-denied");peerMark("alice","final-sent");roomParticipants("Gaming","gaming-membership-after-kick","carol");if(wireHasRoomText("Lobby","Lobby after Carol kick"))throw new AssertionError("Kicked client received later Lobby text");System.out.println("PASS kicked client receives no later Lobby text; Gaming remains active");mark("no-postkick-delivery");peerMark("alice","finished");
 }
 public static void main(String[] args){try{user=args[0];transport=args[1];out=moderationRoot.resolve(user);Connector.out=out;init(false);if(user.equals("carol"))join("Gaming");join("Lobby");mark("joined");if(user.equals("alice"))alice();else if(user.equals("bob"))bob();else carol();logout();Files.writeString(out.resolve("result.txt"),"PASS original v4.62 room moderation: "+user+" over "+transport+"; moderator/muted participant state, denied ordinary kick, mute/unmute, kick and post-kick enforcement.\n");System.out.println("PASS "+user+" room moderation complete");System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
